<script setup lang="ts">
import { onMounted, reactive, ref, watch } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { createMaterial, deleteMaterial, materialReferences, searchMaterials, updateMaterial } from "@/api/material";
import type { MaterialRow, MaterialWriteRequest } from "@/api/material/types";
const rows=ref<MaterialRow[]>([]), total=ref(0), page=ref(1), keyword=ref(""), status=ref(""), loading=ref(false), open=ref(false), editing=ref<number|null>(null);
const form=reactive<MaterialWriteRequest>({materialCode:"",materialName:"",specification:"",baseUnit:"件",materialType:"raw_material",status:"active"});
let timer:number|undefined;
async function load(){loading.value=true;try{const d=await searchMaterials({keyword:keyword.value,status:status.value||undefined,page:page.value,pageSize:20});rows.value=d.rows;total.value=d.total}finally{loading.value=false}}
watch([keyword,status],()=>{window.clearTimeout(timer);timer=window.setTimeout(()=>{page.value=1;void load()},300)});
function edit(row?:MaterialRow){editing.value=row?.materialId??null;Object.assign(form,row?{materialCode:row.materialCode,materialName:row.materialName,specification:row.specification??"",baseUnit:row.baseUnit,materialType:row.materialType,status:row.status}:{materialCode:"",materialName:"",specification:"",baseUnit:"件",materialType:"raw_material",status:"active"});open.value=true}
async function save(){const r=editing.value?await updateMaterial(editing.value,form):await createMaterial(form);if(r.code!==200)return ElMessage.error(r.msg);ElMessage.success(r.msg);open.value=false;await load()}
async function remove(row:MaterialRow){const refs=await materialReferences(row.materialId);await ElMessageBox.confirm(`制造 BOM 引用 ${refs.manufacturingBomCount}，模板引用 ${refs.templateItemCount}。确认删除？`,`删除 ${row.materialCode}`);const r=await deleteMaterial(row.materialId);if(r.code!==200)return ElMessage.error(r.msg);ElMessage.success("已删除");await load()}
onMounted(load);
</script>
<template><div class="p-6 space-y-4"><div class="flex justify-between"><div><h1 class="text-2xl font-semibold">物料库</h1><p class="text-sm text-gray-500">统一维护物料编码、名称、规格与单位关系</p></div><button class="bg-blue-600 text-white rounded px-4" @click="edit()">新增物料</button></div>
<div class="flex gap-3"><input v-model="keyword" class="border rounded px-3 py-2 w-80" placeholder="搜索物料编码或名称"><select v-model="status" class="border rounded px-3"><option value="">全部状态</option><option value="active">启用</option><option value="inactive">停用</option></select></div>
<div class="border rounded overflow-hidden"><table class="w-full text-sm"><thead class="bg-gray-50"><tr><th>物料编码</th><th>物料名称</th><th>规格</th><th>单位</th><th>类型</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.materialId" class="border-t"><td class="font-mono">{{r.materialCode}}</td><td>{{r.materialName}}</td><td>{{r.specification||'-'}}</td><td>{{r.baseUnit}}</td><td>{{r.materialType}}</td><td>{{r.status==='active'?'启用':'停用'}}</td><td><button class="text-blue-600 mr-3" @click="edit(r)">编辑</button><button class="text-red-600" @click="remove(r)">删除</button></td></tr><tr v-if="!loading&&!rows.length"><td colspan="7" class="text-center text-gray-500 py-8">暂无物料</td></tr></tbody></table></div>
<div class="flex justify-end gap-3"><span>共 {{total}} 条</span><button :disabled="page<=1" @click="page--;load()">上一页</button><button :disabled="page*20>=total" @click="page++;load()">下一页</button></div>
<div v-if="open" class="border rounded-lg bg-gray-50 p-5 space-y-4"><div class="flex justify-between items-center"><strong>{{editing?'编辑物料':'新增物料'}}</strong><button class="text-gray-500" @click="open=false">关闭</button></div><div class="grid grid-cols-2 gap-4"><input v-model="form.materialCode" :disabled="!!editing" class="border rounded px-3 py-2" placeholder="物料编码"><input v-model="form.materialName" class="border rounded px-3 py-2" placeholder="物料名称"><input v-model="form.specification" class="border rounded px-3 py-2" placeholder="规格型号"><input v-model="form.baseUnit" class="border rounded px-3 py-2" placeholder="基本单位"><select v-model="form.materialType" class="border rounded px-3"><option value="raw_material">原材料</option><option value="semi_finished">半成品</option><option value="purchased_part">采购件</option><option value="packaging">包装材料</option><option value="auxiliary">辅料</option></select><select v-model="form.status" class="border rounded px-3"><option value="active">启用</option><option value="inactive">停用</option></select></div><div class="flex justify-end gap-3"><button class="px-4 py-2" @click="open=false">取消</button><button class="bg-blue-600 text-white rounded px-4 py-2" @click="save">保存</button></div></div></div></template>
<style scoped>th,td{padding:.75rem;text-align:left}</style>
